async function askNotify() {
  const ok = await showPrimer();          // 내 화면에서 이유를 설명하고 예/아니오
  if (!ok) return;                        // 여기서 거절 = OS 권한은 아직 안 씀
  const perm = await Notification.requestPermission();
  if (perm === 'granted') await subscribePush();
}

const reg = await navigator.serviceWorker.ready;
const sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: VAPID_PUBLIC });
await api.saveSubscription(sub);

// 서비스 워커에서
self.addEventListener('push', (e) => {
  const d = e.data.json();
  e.waitUntil(self.registration.showNotification(d.title, { body: d.body, data: { url: d.url } }));
});
